"""Manual solutions and twelve individually designed battery-efficiency tasks."""
from render import *
from efficiency_figures import *
FAMILY='Effekt och verkningsgrad med inre resistans'
def st(h,tex='',why=''):return h,(p(why) if why else '')+(m(tex) if tex else '')
def sol(steps,answer):return steps,answer
def power(tex='',why=''):return st(r'Inre värmeeffekt: \(P_r=I^2r\)',tex,why)
def eta(tex='',why=''):return st(r'Verkningsgrad: \(\eta=P_{\rm yttre}/P_{\rm tot}\)',tex,why)
def pole(tex='',why=''):return st(r'Polspänning: \(U=\mathcal E-rI\)',tex,why)
def total(tex='',why=''):return st(r'Total effekt: \(P_{\rm tot}=\mathcal E I\)',tex,why)
def outer(tex='',why=''):return st(r'Yttre effekt: \(P_{\rm yttre}=UI\)',tex,why)
def hint(id,h,*cards):
 byid[id]['ledtrad']=p(h)
 for d,h in zip(byid[id].get('spelDelar',[]),cards):d['ledtrad']=p(h)

setq('8.214',[power(r'P_r=2{,}6^2\cdot0{,}35=2{,}366\ \mathrm W','Använd den inre resistansen eftersom det är värmen inne i batteriet som efterfrågas.')],r'\(2{,}366\ \mathrm W\).')
setq('8.215',[eta(r'\eta=\frac{UI}{\mathcal E I}=\frac U{\mathcal E}','Samma ström går genom batteriet och den yttre kretsen. Strömmen förkortas bort i kvoten.'),st('Sätt in spänningarna och skriv i procent',r'\eta=\frac{10}{12}\approx0{,}833=83{,}3\,\%')],r'\(83{,}3\,\%\) når den yttre kretsen.')
a=sol([total(r'P_{\rm tot}=12\cdot3{,}0=36\ \mathrm W','Ems anger omvandlad energi per laddning. Multiplicera med strömmen för att få batteriets totala elektriska effekt.')],r'\(36\ \mathrm W\).')
b=sol([power(r'P_r=3{,}0^2\cdot0{,}40=3{,}6\ \mathrm W')],r'\(3{,}6\ \mathrm W\).')
c=sol([st(r'Effektbalans: \(P_{\rm yttre}=P_{\rm tot}-P_r\)',r'P_{\rm yttre}=36-3{,}6=32{,}4\ \mathrm W','Den effekt som blir värme inne i batteriet når inte den yttre kretsen.')],r'\(32{,}4\ \mathrm W\).')
d=sol([eta(r'\eta=\frac{32{,}4}{36}=0{,}90=90\,\%','Dividera effekten som når den yttre kretsen med hela batteriets effekt.')],r'\(90\,\%\).')
multi('8.45',[a,b,c,d])
hint('8.45','Skilj den totala effekten från värmen inne i batteriet och effekten som når den yttre kretsen.','Vilket samband kopplar ihop ems, ström och total effekt?','Vilken resistans orsakar värmen inne i batteriet?','Hur delas batteriets totala effekt upp?','Jämför den yttre effekten med hela den tillförda effekten.')
setq('8.222',[power(r'P_r=1^2\cdot1{,}1=1{,}1\ \mathrm W')],r'\(1{,}1\ \mathrm W\).')
setq('8.224',[power(r'P_r=1{,}2^2\cdot0{,}9=1{,}296\ \mathrm W')],r'\(1{,}296\ \mathrm W\).')
setq('8.226',[power(r'P_r=1{,}4^2\cdot1{,}1=2{,}156\ \mathrm W')],r'\(2{,}156\ \mathrm W\).')
setq('8.228',[st(r'Inre spänningsfall: \(U_r=rI\)',r'U_r=0{,}9\cdot1{,}1=0{,}99\ \mathrm V'),pole(r'U=9-0{,}99=8{,}01\ \mathrm V','Batteriet levererar ström, så det inre spänningsfallet dras från ems.')],r'\(8{,}01\ \mathrm V\).')
setq('8.230',[st(r'Ohms lag för hela kretsen: \(R+r=\mathcal E/I\)',r'R+r=\frac{9{,}0}{1{,}3}\ \Omega'),st('Dra bort den inre resistansen',r'R=\frac{9{,}0}{1{,}3}-1{,}1\approx5{,}82\ \Omega','Behåll hela kvoten i beräkningen och avrunda först slutsvaret.')],r'\(5{,}82\ \Omega\).')
setq('8.232',[pole(r'U=9{,}0-0{,}90\cdot1{,}0=8{,}1\ \mathrm V'),outer(r'P_{\rm yttre}=8{,}1\cdot1{,}0=8{,}1\ \mathrm W','Det är polspänningen som ligger över den yttre kretsen.')],r'\(8{,}1\ \mathrm W\).')
setq('8.234',[eta(r'\eta=\frac{I^2R}{I^2(R+r)}=\frac R{R+r}','Samma ström går genom inre och yttre resistans. Därför förkortas I² bort.'),st('Sätt in resistanserna',r'\eta=\frac{4{,}0}{4{,}0+0{,}55}\approx0{,}8791=87{,}91\,\%')],r'\(87{,}91\,\%\) utvecklas i den yttre resistorn.')
setq('8.237',[st(r'Inre effektandel: \(P_r/P_{\rm tot}\)',r'\frac{P_r}{P_{\rm tot}}=\frac{I^2r}{I^2(R+r)}=\frac r{R+r}','Täljaren ska innehålla den inre resistansen, eftersom frågan gäller värmen inne i batteriet.'),st('Sätt in resistanserna och skriv i procent',r'\frac{0{,}50}{2{,}0+0{,}50}=0{,}20=20\,\%')],r'\(20\,\%\) blir värme inne i batteriet.')
hint('8.237','Vilken del av den totala effekten utvecklas i den inre resistansen?')
setq('8.240',[eta(r'\eta=\frac{I^2R}{I^2(R+r)}=\frac R{R+r}','Samma ström går genom båda resistanserna. I² kan förkortas bort.'),st('Sätt in resistanserna',r'\eta=\frac{5{,}0}{5{,}0+0{,}45}\approx0{,}9174=91{,}74\,\%')],r'\(91{,}74\,\%\) utvecklas i den yttre resistorn.')
setq('8.242',[st(r'Jämför inre och yttre effekt: \(P_r/P_R=r/R\)',r'\frac{I^2r}{I^2R}=\frac rR=0{,}20','20 % jämförs här med den yttre effekten, inte med den totala. Samma ström går genom båda resistanserna.'),st(r'Lös ut resistansen: \(R=r/0{,}20\)',r'R=\frac{0{,}60}{0{,}20}=3{,}0\ \Omega')],r'\(3{,}0\ \Omega\).')
setq('8.243',[eta(r'\eta=\frac{I^2R}{I^2(R+r)}=\frac R{R+r}','85 % av hela effekten ska nå den yttre resistorn.'),st('Sätt in villkoret och samla R-termerna',r'\begin{aligned}\frac R{R+0{,}40}&=0{,}85\\R&=0{,}85R+0{,}34\\0{,}15R&=0{,}34\\R&\approx2{,}27\ \Omega\end{aligned}')],r'\(2{,}27\ \Omega\).')
assert len(changes)==14
save()

# New, individually designed tasks; numeric keys are stored at full precision.
new=[]
def add(id,level,text,fig,steps,answer,value,unit,h,ability=('procedur',),gg=False,precision=2,labels=None):
 q={'id':id,'kap':8,'omr':'kopplingar','familj':FAMILY,'familjNyckel':'ems__effekt_och_verkningsgrad','niva':'E' if level<3 else 'C','poang':'(1/0/0)' if level<3 else '(0/2/0)' if level==4 else '(0/1/0)','traningsniva':level,'arbetsinsats':1 if level<3 else 2 if level==3 else 3,'formaga':list(ability),'t':text+fig,'s':solution(steps,answer),'ledtrad':p(h),'spel':True,'miniräknare':True,'geogebra':gg,'manuellKomplettering':False,'svarstyp':'numeriskt','svarFormat':'numeriskt','rättSvar':value,'tolerans':max(1e-9,abs(value)*.005) if not isinstance(value,list) else [max(1e-9,abs(v)*.005) for v in value],'svarEnhet':unit,'självrättning':True,'svarVardesiffror':precision}
 if labels:q.update(svarstyp='flera_delar',svarFormat=['numeriskt']*len(value),självrättning=[True]*len(value),svarsstruktur='ordnad',svarEtiketter=labels,svarVardesiffror=[precision]*len(value))
 new.append(q)

add('8.727',1,p('Ett batteri omvandlar 500 J kemisk energi till elektrisk energi. Av detta blir 100 J värme inne i batteriet. Hur mycket energi når den yttre kretsen? (Svara i J.)'),flow(),[st(r'Energibalans: \(E_{\rm yttre}=E_{\rm tot}-Q\)',r'E_{\rm yttre}=500-100=400\ \mathrm J','Den inre värmen är den del som inte når den yttre kretsen.')],r'\(400\ \mathrm J\).',400,'J','Följ energins två vägar i figuren.')
add('8.728',2,p('Ett batteri med ems 6,0 V levererar strömmen 0,40 A. En liten radio tar emot 2,0 W från batteriet. Hur stor effekt blir värme inne i batteriet? (Svara i W.)'),circuit('ε = 6,0 V','r = ?','Radio','0,40 A'),[total(r'P_{\rm tot}=6{,}0\cdot0{,}40=2{,}4\ \mathrm W'),st(r'Effektbalans: \(P_r=P_{\rm tot}-P_{\rm yttre}\)',r'P_r=2{,}4-2{,}0=0{,}40\ \mathrm W')],r'\(0{,}40\ \mathrm W\).',.4,'W','Jämför batteriets totala elektriska effekt med effekten som radion tar emot.')
add('8.729',3,p('En radiosändare drar 2,0 A i 10 s och därefter 0,20 A i 50 s, som grafen visar. Batteriets inre resistans är 0,50 Ω. Hur mycket värme bildas inne i batteriet under hela minuten? (Svara i J.)'),pulse(),[power(r'\begin{aligned}P_1&=2{,}0^2\cdot0{,}50=2{,}0\ \mathrm W\\P_2&=0{,}20^2\cdot0{,}50=0{,}020\ \mathrm W\end{aligned}','Beräkna värmeeffekten separat under sändning och vila. Medelströmmen kan inte kvadreras för att få rätt medeleffekt.'),st(r'Värmeenergi: \(Q=P_1t_1+P_2t_2\)',r'Q=2{,}0\cdot10+0{,}020\cdot50=21\ \mathrm J')],r'\(21\ \mathrm J\).',21,'J','Beräkna värmen för varje tidsintervall. Hur påverkas effekten när strömmen kvadreras?',('problemlösning','procedur'))
add('8.730',3,p('Två batterier A och B provas med samma resistor på 4,0 Ω, ett batteri i taget. Deras ems och inre resistanser visas i figuren. Hur många gånger så stor effekt får resistorn med batteri A som med batteri B?'),compare(),[st(r'Ström: \(I=\mathcal E/(R+r)\)',r'\begin{aligned}I_A&=\frac{12}{4{,}0+0{,}20}=\frac{20}{7}\ \mathrm A\\I_B&=\frac{12}{4{,}0+1{,}0}=2{,}4\ \mathrm A\end{aligned}'),st(r'Effektkvot: \(P_A/P_B=(I_A/I_B)^2\)',r'\frac{P_A}{P_B}=\left(\frac{20/7}{2{,}4}\right)^2\approx1{,}42','Samma yttre resistans finns i båda försöken och förkortas bort i kvoten.')],r'Cirka \(1{,}42\) gånger så stor.',(5/4.2)**2,None,'Samma ems betyder inte samma ström. Jämför först hela kretsens resistans.',('problemlösning','procedur'))
add('8.731',3,p('Ett batteri med ems 12 V och inre resistans 1,0 Ω driver två parallella resistorer på 6,0 Ω och 3,0 Ω. Hur många procent av batteriets totala elektriska effekt utvecklas i resistorn på 3,0 Ω? (Svara i procent.)'),circuit('ε = 12 V','r = 1,0 Ω','3,0 Ω',parallel=True),[st(r'Parallellresistans: \(R_p=R_1R_2/(R_1+R_2)\)',r'R_p=\frac{6{,}0\cdot3{,}0}{6{,}0+3{,}0}=2{,}0\ \Omega'),st(r'Totalström: \(I=\mathcal E/(R_p+r)\)',r'I=\frac{12}{2{,}0+1{,}0}=4{,}0\ \mathrm A'),st(r'Ohms lag: \(U=R_pI\)',r'U=2{,}0\cdot4{,}0=8{,}0\ \mathrm V','Samma polspänning ligger över båda parallella resistorerna.'),st(r'Greneffekt: \(P_3=U^2/R_3\)',r'P_3=\frac{8{,}0^2}{3{,}0}=\frac{64}{3}\ \mathrm W'),total(r'P_{\rm tot}=12\cdot4{,}0=48\ \mathrm W'),st('Jämför grenens effekt med hela batteriets effekt',r'\frac{P_3}{P_{\rm tot}}=\frac{64/3}{48}\approx0{,}444=44{,}4\,\%')],r'\(44{,}4\,\%\).',400/9,'%', 'Skilj totalströmmen genom batteriet från strömmen i den efterfrågade grenen.',('problemlösning','procedur'))
add('8.732',3,p('En batteridriven motor lyfter en last på 8,0 kg med konstant fart. Batteriet har ems 12 V, polspänningen 10 V och strömmen 2,0 A. Motorn omvandlar 75 % av den mottagna elektriska effekten till arbete på lasten. Hur lång tid tar det att lyfta lasten 3,0 m? (Svara i s.)'),motor(),[outer(r'P_{\rm el}=10\cdot2{,}0=20\ \mathrm W','Motorn får polspänningen, inte hela ems, över sig.'),st(r'Mekanisk effekt: \(P_{\rm mek}=\eta_{\rm motor}P_{\rm el}\)',r'P_{\rm mek}=0{,}75\cdot20=15\ \mathrm W'),st(r'Lyftarbete: \(W=mgh\)',r'W=8{,}0\cdot9{,}82\cdot3{,}0=235{,}68\ \mathrm J','Farten är konstant. Arbetet ökar lastens lägesenergi.'),st(r'Tid: \(t=W/P_{\rm mek}\)',r't=\frac{235{,}68}{15}=15{,}712\ \mathrm s')],r'Cirka \(16\ \mathrm s\).',8*9.82*3/15,'s','Vilken spänning får motorn? Följ sedan energin från el till lyftarbete.',('problemlösning','procedur'))
add('8.733',3,p('Ett batteri med ems 9,0 V och inre resistans 0,50 Ω kopplas till en resistor R. Värmeeffekten inne i batteriet får vara högst 0,50 W. Hur liten får den yttre resistansen vara? (Svara i Ω.)'),circuit('ε = 9,0 V','r = 0,50 Ω','R = ?'),[power(r'I_{\max}=\sqrt{\frac{0{,}50}{0{,}50}}=1{,}0\ \mathrm A','Värmegränsen ger den största tillåtna strömmen.'),st(r'Ohms lag för hela kretsen: \(R+r=\mathcal E/I\)',r'R_{\min}=\frac{9{,}0}{1{,}0}-0{,}50=8{,}5\ \Omega'),st('Kontrollera gränsens riktning',why='En mindre yttre resistans skulle ge större ström och därmed mer än 0,50 W värme inne i batteriet.')],r'Minst \(8{,}5\ \Omega\).',8.5,'Ω','Börja med den största ström som värmegränsen tillåter.',('problemlösning','procedur'))
add('8.734',3,p('Tabellen visar två mätningar på samma batteri. Batteriets ems och inre resistans är oförändrade. Hur stor värmeeffekt utvecklas inne i batteriet när strömmen är 1,5 A? (Svara i W.)'),data_table(),[pole(why='När strömmen ökar kommer sänkningen av polspänningen från det ökade inre spänningsfallet.'),st(r'Inre resistans: \(r=(U_1-U_2)/(I_2-I_1)\)',r'r=\frac{5{,}5-5{,}0}{1{,}0-0{,}50}=1{,}0\ \Omega'),power(r'P_r=1{,}5^2\cdot1{,}0=2{,}25\ \mathrm W')],r'\(2{,}25\ \mathrm W\).',2.25,'W','Vad kan spänningens förändring och strömmens förändring berätta om batteriet?',('problemlösning','procedur'))
add('8.735',4,p('Ett batteri med ems 6,0 V och inre resistans 1,0 Ω ska ge effekten 8,0 W i en yttre resistor. Två olika resistanser är möjliga. Välj den som gör att störst andel av batteriets totala elektriska effekt når resistorn. Bestäm resistansen och denna andel. (Svara i Ω respektive procent.)'),circuit('ε = 6,0 V','r = 1,0 Ω','R = ?'),[pole(r'U=6{,}0-I'),outer(r'8{,}0=(6{,}0-I)I','Strömmen är okänd. Sätt in polspänningen i uttrycket för den yttre effekten.'),('Lös effektekvationen grafiskt',p('Rita P(I) = 6I − I² och linjen P = 8 i GeoGebra. Skärningarna ger I = 2,0 A och I = 4,0 A.')+powergraph()),eta(r'\eta=\frac{8{,}0}{6{,}0I}','Den yttre effekten är densamma. Mindre ström ger mindre total tillförd effekt och därför högre verkningsgrad. Välj I = 2,0 A.'),st(r'Resistans från effekt: \(R=P/I^2\)',r'R=\frac{8{,}0}{2{,}0^2}=2{,}0\ \Omega'),eta(r'\eta=\frac{8{,}0}{6{,}0\cdot2{,}0}\approx0{,}667=66{,}7\,\%'),st('Kontrollera det andra alternativet',r'\begin{aligned}R&=\frac8{4^2}=0{,}50\ \Omega\\\eta&=\frac8{6\cdot4}\approx33{,}3\,\%\end{aligned}','Det andra alternativet ger samma yttre effekt men mer värme inne i batteriet.')],r'\(2{,}0\ \Omega\) och \(66{,}7\,\%\).',[2,200/3],['Ω','%'],'Skriv den yttre effekten med strömmen som okänd. Jämför sedan de två möjliga strömmarnas inre förluster.',('problemlösning','procedur'),gg=True,labels=['Resistans (Ω)','Andel (%)'])
add('8.736',4,p('Två likadana celler har ems 1,5 V och inre resistans 0,50 Ω vardera. De ska driva en resistor på 1,0 Ω. Cellerna kan kopplas i serie eller parallellt, med samma polaritet. Minst 70 % av cellernas totala elektriska effekt ska nå resistorn. Hur stor effekt får resistorn med den koppling som uppfyller kravet? (Svara i W.)'),cellpair(),[st(r'Cellernas sammanlagda ems och resistans',r'\begin{aligned}\mathcal E_s&=3{,}0\ \mathrm V,&r_s&=1{,}0\ \Omega\\\mathcal E_p&=1{,}5\ \mathrm V,&r_p&=0{,}25\ \Omega\end{aligned}','I serie adderas ems och inre resistans. Identiska parallella celler behåller ems men halverar den inre resistansen.'),eta(r'\begin{aligned}\eta_s&=\frac{1{,}0}{1{,}0+1{,}0}=50\,\%\\\eta_p&=\frac{1{,}0}{1{,}0+0{,}25}=80\,\%\end{aligned}','För en yttre resistor är effektandelen R/(R+r). Bara parallellkopplingen klarar kravet.'),st(r'Ström i parallellfallet: \(I=\mathcal E_p/(R+r_p)\)',r'I=\frac{1{,}5}{1{,}0+0{,}25}=1{,}2\ \mathrm A'),st(r'Yttre effekt: \(P_R=I^2R\)',r'P_R=1{,}2^2\cdot1{,}0=1{,}44\ \mathrm W')],r'\(1{,}44\ \mathrm W\), med cellerna parallellkopplade.',1.44,'W','Pröva först verkningsgraden för de två kopplingarna. Störst effekt behöver inte betyda högst verkningsgrad.',('problemlösning','procedur'))
add('8.737',2,p('Under 60 s bildas 72 J värme inne i ett batteri. Strömmen är hela tiden 2,0 A. Bestäm batteriets inre resistans. (Svara i Ω.)'),heat(),[st(r'Värmeeffekt: \(P_r=Q/t\)',r'P_r=\frac{72}{60}=1{,}2\ \mathrm W'),power(r'r=\frac{P_r}{I^2}=\frac{1{,}2}{2{,}0^2}=0{,}30\ \Omega')],r'\(0{,}30\ \Omega\).',.3,'Ω','Gå från värmeenergi till effekt innan du bestämmer resistansen.')
add('8.738',1,p('När ett batteri åldras blir dess inre resistans tre gånger så stor. En strömreglerad apparat håller strömmen genom batteriet oförändrad. Hur många gånger så stor blir värmeeffekten inne i batteriet?'),ageing(),[power(r'P_{\rm ny}=I^2\cdot3r=3P_{\rm gammal}','Strömmen är oförändrad. Då är värmeeffekten direkt proportionell mot den inre resistansen.')],r'Tre gånger så stor.',3,None,'Vilken storhet ändras i sambandet mellan ström, resistans och värmeeffekt?',('begrepp',))
