existing=set(byid)&{q['id'] for q in new}
if existing:
 assert len(existing)==12
 for q in new:
  start=s.index('  {\n    "id": "'+q['id']+'",')+2
  _,end=json.JSONDecoder().raw_decode(s[start:])
  replacement=json.dumps(q,ensure_ascii=False,indent=2).replace('\n','\n  ')
  s=s[:start]+replacement+s[start+end:]
else:
 end=s.rfind(']');assert s[end:].strip()=='];'
 addition=',\n'+',\n'.join('  '+json.dumps(q,ensure_ascii=False,indent=2).replace('\n','\n  ') for q in new)+'\n'
 s=s[:end].rstrip()+addition+s[end:]
